571	<body>
572	  <button type="button" class="help-btn" id="help-btn" aria-label="Show keyboard shortcuts" title="Help (press ?)">?</button>
573	
574	  <div class="modal" id="help-modal" role="dialog" aria-labelledby="modal-header" aria-modal="true">
575	    <div class="modal-content">
576	      <button type="button" class="modal-close" id="modal-close" aria-label="Close help">✕</button>
577	      <div class="modal-header" id="modal-header">Keyboard Shortcuts</div>
578	      <div class="modal-shortcuts">
579	        <div class="shortcut-item">
580	          <span class="shortcut-key">C / →</span>
581	          <span class="shortcut-desc">Cycle to next color</span>
582	        </div>
583	        <div class="shortcut-item">
584	          <span class="shortcut-key">←</span>
