631	  <script defer>
632	    (() => {
633	      const COLORS = [
634	        { class: 'default', name: 'Default White' },
635	        { class: 'color-mode-1', name: 'Pink' },
636	        { class: 'color-mode-2', name: 'Teal' },
637	        { class: 'color-mode-3', name: 'Mint' },
638	        { class: 'color-mode-4', name: 'Purple' },
639	        { class: 'color-mode-5', name: 'Orange' },
640	        { class: 'color-mode-6', name: 'Coral' },
641	        { class: 'color-mode-7', name: 'Cyan' }
642	      ];
643	
644	      const getRandomColorMode = () => Math.floor(Math.random() * COLORS.length);
645	      const isTouch = (() => {
646	        if (!window.matchMedia) return false;
647	        const hasCoarsePointer = window.matchMedia('(pointer:coarse)').matches;
648	        const hasTouchEvents = 'ontouchstart' in window;
649	        const hasMaxTouchPoints = (navigator.maxTouchPoints ?? 0) > 0;
650	        return hasCoarsePointer || hasTouchEvents || hasMaxTouchPoints;
