662	      const el = {
663	        circle: document.getElementById('decorative-circle'),
664	        hint: document.getElementById('hint-text'),
665	        modeIndicator: document.getElementById('mode-indicator'),
666	        cycleBtn: document.getElementById('cycle-btn'),
667	        randomBtn: document.getElementById('random-btn'),
668	        resetBtn: document.getElementById('reset-btn'),
669	        helpBtn: document.getElementById('help-btn'),
670	        helpModal: document.getElementById('help-modal'),
671	        modalClose: document.getElementById('modal-close')
672	      };
673	
674	      let state = { active: false, colorMode: 0 };
675	      let tapCount = 0;
676	      let tapTimeout = null;
677	      let animatingColorShift = false;
678	      let saveTimeout = null;
679	      let lastKeyTime = 0;
680	
681	      const haptic = (duration) => navigator.vibrate?.(duration);
682	
683	      const getColorClass = (mode) => COLORS[mode % COLORS.length]?.class || '';
684	      const getColorName = (mode) => COLORS[mode % COLORS.length]?.name || '';
685	
686	      const storage = {
687	        save() {
688	          clearTimeout(saveTimeout);
689	          saveTimeout = setTimeout(() => {
690	            try {
691	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
692	            } catch (e) {
693	              // Silently fail on storage errors
694	            }
695	          }, CONFIG.saveDebounceDuration);
696	        },
697	        load() {
