699	            const saved = localStorage.getItem(CONFIG.storageKey);
700	            if (saved) {
701	              const parsed = JSON.parse(saved);
702	              if (parsed?.active !== undefined && parsed?.colorMode !== undefined) {
703	                state = parsed;
704	              }
705	            }
706	          } catch (e) {
