770	          }, 0);
771	        }
772	      };
773	
774	      const toggleActive = () => {
775	        state.active = !state.active;
776	        haptic(10);
777	        applyState();
778	        storage.save();
779	      };
780	
781	      const changeColor = (newMode, hapticPattern = 20) => {
782	        if (animatingColorShift || !el.circle) return;
783	        animatingColorShift = true;
784	        state.colorMode = newMode;
785	        state.active = true;
