790	          animatingColorShift = false;
791	        }, CONFIG.colorShiftDuration);
792	        applyState();
793	        storage.save();
794	        return () => clearTimeout(animTimeout);
795	      };
796	
797	      const cycleColor = () => changeColor((state.colorMode + 1) % COLORS.length);
798	      const randomizeColor = () => changeColor(getRandomColorMode(), [20, 10, 20]);
799	
800	      const resetState = () => {
801	        state = { active: false, colorMode: 0 };
