825	      const keyHandlers = {
826	        ' ': toggleActive,
827	        'enter': toggleActive,
828	        'escape': resetState,
829	        'c': cycleColor,
830	        'x': randomizeColor,
831	        'r': resetState,
832	        '?': modal.open,
833	        'arrowright': cycleColor,
834	        'arrowleft': () => {
835	          if (animatingColorShift || !el.circle) return;
836	          const newMode = (state.colorMode - 1 + COLORS.length) % COLORS.length;
837	          changeColor(newMode);
838	        }
839	      };
840	
841	      const handleKeyDown = (e) => {
842	        const key = e.key.toLowerCase();
843	        const handler = keyHandlers[key];
844	        if (!handler) return;
845	
846	        const now = Date.now();
847	        if (now - lastKeyTime < CONFIG.keyDebounce) return;
848	
849	        e.preventDefault();
850	        handler();
851	        lastKeyTime = now;
852	      };
853	
854	      const handleModalKeyDown = (e) => {
855	        if (!el.helpModal?.classList.contains('active')) return;
856	
857	        if (e.key === 'Escape') {
858	          e.preventDefault();
859	          modal.close();
860	          return;
861	        }
862	
863	        if (e.key === 'Tab') {
864	          const focusableElements = Array.from(el.helpModal.querySelectorAll('button, [tabindex]')).filter(el => !el.hasAttribute('disabled'));
865	          if (focusableElements.length === 0) return;
866	
867	          const firstElement = focusableElements[0];
868	          const lastElement = focusableElements[focusableElements.length - 1];
