870	
871	          if (e.shiftKey) {
872	            if (activeElement === firstElement) {
873	              e.preventDefault();
874	              lastElement.focus();
875	            }
876	          } else {
877	            if (activeElement === lastElement) {
878	              e.preventDefault();
879	              firstElement.focus();
880	            }
881	          }
882	        }
883	      };
