const handleModalKeyDown = (e) => {
  if (!el.helpModal?.classList.contains('active')) return;

  if (e.key === 'Escape') {
    e.preventDefault();
    modal.close();
    return;
  }

  if (e.key === 'Tab') {
    const focusableElements = Array.from(el.helpModal.querySelectorAll('button, [tabindex]')).filter(el => !el.hasAttribute('disabled'));
    if (focusableElements.length === 0) return;

    const firstElement = focusableElements[0];
    const lastElement = focusableElements[focusableElements.length - 1];
    const activeElement = document.activeElement;

    if (e.shiftKey) {
      if (activeElement === firstElement) {
        e.preventDefault();
        lastElement.focus();
      }
    } else {
      if (activeElement === lastElement) {
        e.preventDefault();
        firstElement.focus();
      }
    }
  }
};

