    tapCount = 0;
    clearTimeout(tapTimeout);
  });

  if (isTouch) {
    el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
    if (window.PointerEvent) {
      el.circle.addEventListener('pointerup', handleTouchEnd, { passive: true });
    }
  } else {
    el.circle.addEventListener('click', toggleActive);
    el.circle.addEventListener('dblclick', cycleColor);
  }

  document.addEventListener('keydown', handleKeyDown);

  el.cycleBtn?.addEventListener('click', cycleColor);
  el.randomBtn?.addEventListener('click', randomizeColor);
  el.resetBtn?.addEventListener('click', resetState);
  el.helpBtn?.addEventListener('click', modal.open);
  el.modalClose?.addEventListener('click', modal.close);
  el.helpModal?.addEventListener('click', handleModalBackdropClick);
  el.helpModal?.addEventListener('keydown', handleModalKeyDown);
};

